export function validateSuiteManifest(scripts) {
  const errors = [];
  const ids = new Set();
  for (const suite of suiteManifest) {
    if (ids.has(suite.id)) errors.push(`Duplicate suite id: ${suite.id}`);
    ids.add(suite.id);
    if (!scripts[suite.script]) errors.push(`Suite ${suite.id} references missing package script ${suite.script}`);
    if (!Array.isArray(suite.features) || suite.features.length === 0) errors.push(`Suite ${suite.id} has no features`);
    if (!["fast", "local", "browser", "benchmark"].includes(suite.tier)) errors.push(`Suite ${suite.id} has invalid tier ${suite.tier}`);
    if (!["none", "local", "external"].includes(suite.network)) errors.push(`Suite ${suite.id} has invalid network boundary`);
  }
  return errors;
}
